// Validation et préparation des données
const input = $input.first().json;
const body = input.body || input;

const startTime = Date.now();

// Extraction des paramètres
const text = body.text || '';
const openaiApiKey = body.openai_api_key || '';
const sourceTextId = body.source_text_id || null;
const commentaryId = body.commentary_id || null;
const context = body.context || {};

// Validation
const errors = [];
if (!text || text.trim().length === 0) {
  errors.push('Le champ "text" est requis');
}
if (!openaiApiKey || openaiApiKey.trim().length === 0) {
  errors.push('Le champ "openai_api_key" est requis');
}

// Construire les paramètres de recherche cache
let cacheSearchParams = '';
if (sourceTextId) {
  cacheSearchParams = `source_text_id=${sourceTextId}`;
} else if (commentaryId) {
  cacheSearchParams = `commentary_id=${commentaryId}`;
} else if (context.traite && context.page) {
  cacheSearchParams = `traite=${encodeURIComponent(context.traite)}&page=${encodeURIComponent(context.page)}`;
  if (context.commentator) {
    cacheSearchParams += `&commentator=${encodeURIComponent(context.commentator)}`;
  }
}

return [{
  json: {
    valid: errors.length === 0,
    errors: errors,
    text: text,
    openaiApiKey: openaiApiKey,
    sourceTextId: sourceTextId,
    commentaryId: commentaryId,
    context: context,
    startTime: startTime,
    cacheSearchParams: cacheSearchParams,
    canSearchCache: !!(sourceTextId || commentaryId || (context.traite && context.page)),
    isCommentary: !!commentaryId
  }
}];

// Vérifier si le cache a retourné une vocalisation
const input = $input.first().json;
const prevData = $('Validate Input').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

// Cache hit si status 200 et vocalisation trouvée
const cacheHit = statusCode === 200 && data.found === true && data.vocalized_text;

if (cacheHit) {
  return [{
    json: {
      cacheHit: true,
      vocalizedText: data.vocalized_text,
      vocalizedBy: data.vocalized_by || 'cached',
      vocalizedAt: data.vocalized_at,
      // Passer les données pour la réponse
      originalText: prevData.text,
      sourceTextId: data.source_text_id || prevData.sourceTextId,
      commentaryId: data.commentary_id || prevData.commentaryId,
      context: prevData.context,
      startTime: prevData.startTime
    }
  }];
}

// Cache miss - passer au LLM
return [{
  json: {
    cacheHit: false,
    ...prevData
  }
}];

// Formater la réponse depuis le cache
const input = $input.first().json;

const endTime = Date.now();
const processingTime = endTime - input.startTime;

return [{
  json: {
    success: true,
    cached: true,
    vocalization: {
      original: input.originalText,
      vocalized: input.vocalizedText
    },
    metadata: {
      traite: input.context.traite || null,
      page: input.context.page || null,
      commentator: input.context.commentator || null,
      source_text_id: input.sourceTextId || null,
      commentary_id: input.commentaryId || null,
      vocalized_by: input.vocalizedBy,
      source: 'cache',
      cached_at: input.vocalizedAt,
      processing_time_ms: processingTime
    }
  }
}];

