// Extraire la vocalisation et préparer la sauvegarde
const input = $input.first().json;
const prevData = $('Validate Input').first().json;

const endTime = Date.now();
const processingTime = endTime - prevData.startTime;

// Gestion fullResponse ou réponse directe
const data = input.body || input;
const statusCode = input.statusCode || 200;

// Vérifier les erreurs
const hasError = statusCode >= 400 || !!data.error;
if (hasError) {
  const errorMsg = data.error?.message || `Erreur HTTP ${statusCode}`;
  return [{
    json: {
      success: false,
      error: {
        code: statusCode >= 400 ? statusCode : 401,
        message: `Erreur API OpenAI: ${errorMsg}`,
        status: 'OPENAI_API_ERROR'
      }
    }
  }];
}

// Extraire le texte vocalisé
let vocalizedText = '';
if (data.choices && data.choices[0]?.message?.content) {
  vocalizedText = data.choices[0].message.content.trim();
}

if (!vocalizedText) {
  return [{
    json: {
      success: false,
      error: {
        code: 500,
        message: 'Aucune vocalisation retournée par GPT',
        status: 'EMPTY_GPT_RESPONSE'
      }
    }
  }];
}

const usage = data.usage || {};

// Construire la réponse
const response = {
  success: true,
  cached: false,
  vocalization: {
    original: prevData.text,
    vocalized: vocalizedText
  },
  metadata: {
    traite: prevData.context.traite || null,
    page: prevData.context.page || null,
    commentator: prevData.context.commentator || null,
    source_text_id: prevData.sourceTextId || null,
    commentary_id: prevData.commentaryId || null,
    vocalized_by: 'llm:gpt-4o',
    model: 'gpt-4o',
    source: 'generated',
    processing_time_ms: processingTime,
    tokens: {
      prompt_tokens: usage.prompt_tokens || 0,
      completion_tokens: usage.completion_tokens || 0
    }
  },
  // Données pour sauvegarde
  _saveData: {
    source_text_id: prevData.sourceTextId,
    commentary_id: prevData.commentaryId,
    vocalized_text: vocalizedText,
    vocalized_by: 'llm:gpt-4o'
  }
};

return [{ json: response }];

// Nettoyer la réponse (supprimer _saveData)
const prevResponse = $('Extract GPT Response').first().json;

// Supprimer les données internes
const response = { ...prevResponse };
delete response._saveData;

return [{ json: response }];

// Construire la réponse d'erreur de validation
const input = $input.first().json;

return [{
  json: {
    success: false,
    error: {
      code: 400,
      message: input.errors.join(', '),
      status: 'BAD_REQUEST'
    }
  }
}];

// Vérifier si le commentaire a des nekudot
const input = $input.first().json;
const prevData = $('Validate Input').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

// Si erreur API, passer à la vocalisation
if (statusCode >= 400) {
  return [{
    json: {
      hasNekudot: false,
      ...prevData
    }
  }];
}

// Vérifier si les nekudot existent
const nekudot = data.nekudot || {};
const nekudotData = nekudot[prevData.commentaryId];

if (nekudotData && nekudotData.text) {
  return [{
    json: {
      hasNekudot: true,
      cachedNekudot: nekudotData.text,
      cachedAt: nekudotData.vocalized_at,
      originalText: prevData.text,
      context: prevData.context,
      startTime: prevData.startTime,
      commentaryId: prevData.commentaryId
    }
  }];
}

// Pas de nekudot, passer à GPT-4o
return [{
  json: {
    hasNekudot: false,
    ...prevData
  }
}];

// Formater la réponse pour les nekudot depuis la BDD
const input = $input.first().json;

const endTime = Date.now();
const processingTime = endTime - input.startTime;

return [{
  json: {
    success: true,
    cached: true,
    vocalization: {
      original: input.originalText,
      vocalized: input.cachedNekudot
    },
    metadata: {
      traite: input.context.traite || null,
      page: input.context.page || null,
      commentator: input.context.commentator || null,
      commentary_id: input.commentaryId,
      vocalized_by: 'database',
      source: 'database',
      cached_at: input.cachedAt,
      processing_time_ms: processingTime
    }
  }
}];
